-- Read-only preparation. Never invokes a business RPC.
begin read only;
set local search_path=pg_catalog;
set local statement_timeout='30s';
select jsonb_build_object('phase','preflight','pid',pg_backend_pid(),'read_only',current_setting('transaction_read_only'),'database',current_database(),'user',current_user,'server_major',current_setting('server_version_num')::int/10000,
 'snapshot',jsonb_build_object(
 'history',(select jsonb_agg(jsonb_build_object('version',version,'name',name) order by version) from supabase_migrations.schema_migrations),
 'functions_hash',(select md5(string_agg(p.oid::regprocedure::text||'/'||replace(pg_get_functiondef(p.oid),chr(13),'')||'/'||pg_get_userbyid(p.proowner)||'/'||coalesce(p.proacl::text,'') ,E'\n' order by p.oid::regprocedure::text collate "C")) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','elara_private') and p.prokind='f' and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e')),
 'metadata',jsonb_build_object(
  'columns',(select jsonb_agg(jsonb_build_array(a.attrelid::regclass::text,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) order by a.attrelid::regclass::text,a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid in ('public.company_contacts'::regclass,'public.persons'::regclass,'public.customers'::regclass,'public.companies'::regclass,'supabase_migrations.schema_migrations'::regclass) and a.attnum>0 and not a.attisdropped),
  'constraints',(select jsonb_agg(jsonb_build_array(conrelid::regclass::text,conname,pg_get_constraintdef(oid),convalidated) order by conrelid::regclass::text,conname) from pg_constraint where conrelid in ('public.company_contacts'::regclass,'public.persons'::regclass,'public.customers'::regclass,'public.companies'::regclass,'supabase_migrations.schema_migrations'::regclass)),
  'indexes',(select jsonb_agg(jsonb_build_array(indexrelid::regclass::text,pg_get_indexdef(indexrelid),indisvalid,indisready) order by indexrelid::regclass::text) from pg_index where indrelid='public.company_contacts'::regclass),
  'triggers',(select jsonb_agg(jsonb_build_array(tgrelid::regclass::text,tgname,tgenabled,pg_get_triggerdef(oid)) order by tgrelid::regclass::text,tgname) from pg_trigger where tgrelid in ('public.company_contacts'::regclass,'public.persons'::regclass,'public.customers'::regclass,'public.companies'::regclass,'supabase_migrations.schema_migrations'::regclass) and not tgisinternal),
  'tables',(select jsonb_agg(jsonb_build_array(oid::regclass::text,pg_get_userbyid(relowner),relacl::text,relrowsecurity,relforcerowsecurity) order by oid::regclass::text) from pg_class where oid in ('public.company_contacts'::regclass,'public.persons'::regclass,'public.customers'::regclass,'public.companies'::regclass,'public.audit_logs'::regclass,'supabase_migrations.schema_migrations'::regclass)),
  'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname='public' and tablename in ('company_contacts','persons','customers','companies','audit_logs')),
  'schemas',(select jsonb_agg(jsonb_build_array(nspname,nspacl::text) order by nspname) from pg_namespace where nspname in ('public','elara_private','extensions'))
 )),
 'installed_0055',(select count(*)=1 from supabase_migrations.schema_migrations where version='20261116005500' and name='0055_admin_create_company_customer'),
 'source_0055_matches',(select encode(extensions.digest(array_to_string(statements,''),'sha256'),'hex')='31d5747d750b084055bc2f2628052df92e68e634c132402e73aa9300e7504723' from supabase_migrations.schema_migrations where version='20261116005500'),
 'new_objects_absent',not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','elara_private') and p.proname in ('admin_add_company_contact','admin_set_company_primary_contact','admin_update_company_contact','company_contact_version','company_contact_company')) and not exists(select 1 from information_schema.columns where table_schema='public' and table_name='company_contacts' and column_name='version') and not exists(select 1 from supabase_migrations.schema_migrations where version='20261117005600' or name ilike '%0056%'),
 'dependencies',(select jsonb_agg(jsonb_build_object('signature',s,'exists',to_regprocedure(s) is not null,'owner',(select pg_get_userbyid(proowner) from pg_proc where oid=to_regprocedure(s)))) from unnest(array['public.require_admin_user()','elara_private.catalog_request(text,uuid,jsonb)','elara_private.catalog_person(text,text,text,text,text)','elara_private.catalog_audit(text,text,text,uuid,text,jsonb,jsonb,text,uuid,jsonb,jsonb)','public.validate_people_commercial_integrity()','public.set_updated_at()','public.admin_create_company_customer(uuid,text,text,text,text,text,text,text,text,text,jsonb)']) s),
 'indexes_compatible',(select count(*)=2 and bool_and(indisvalid and indisready and indisunique) from pg_index where indexrelid in (to_regclass('public.company_contacts_one_active_per_company_person_idx'),to_regclass('public.company_contacts_one_primary_active_per_company_idx'))),
 'deferred_trigger_compatible',exists(select 1 from pg_trigger where tgrelid='public.company_contacts'::regclass and tgname='validate_company_contacts_integrity' and tgdeferrable and tginitdeferred and tgenabled='O'),
 'privileges_compatible',has_schema_privilege('postgres','public','CREATE') and has_schema_privilege('postgres','elara_private','CREATE') and has_table_privilege('postgres','supabase_migrations.schema_migrations','INSERT') and (select relowner='postgres'::regrole from pg_class where oid='public.company_contacts'::regclass),
 'unsafe_schema_create',exists(select 1 from unnest(array['anon','authenticated']) r cross join unnest(array['public','extensions','elara_private']) n where has_schema_privilege(r,n,'CREATE')),
 'direct_api_writes',exists(select 1 from unnest(array['anon','authenticated']) r cross join unnest(array['company_contacts','persons','customers','companies','audit_logs']) t where has_table_privilege(r,'public.'||t,'INSERT,UPDATE,DELETE,TRUNCATE') or has_any_column_privilege(r,'public.'||t,'INSERT,UPDATE')),
 'conflicting_locks',(select count(*) from pg_locks where pid<>pg_backend_pid() and relation in ('public.company_contacts'::regclass,'supabase_migrations.schema_migrations'::regclass) and (relation='public.company_contacts'::regclass or mode<>'AccessShareLock')),
 'migration_activity',(select count(*) from pg_stat_activity where pid<>pg_backend_pid() and datname=current_database() and state in ('active','idle in transaction') and query ~* '(^|;)[[:space:]]*(create|alter|drop|grant|revoke|do|call|reindex|truncate)[[:space:]]'));
select jsonb_build_object('phase','inside','pid',pg_backend_pid(),'read_only',current_setting('transaction_read_only'));
rollback;
select jsonb_build_object('phase','after','pid',pg_backend_pid());
